 applyStream(){const court=document.getElementById('stream-court').value,type=document.getElementById('stream-type').value,url=document.getElementById('stream-url').value.trim();if(!court)return U.toast('Chọn sân','err');const c=this.state.courts[court]||{id:court};T.Data.queueSet('courts/'+court,{...c,stream:{type,url,status:'LIVE'},updatedAt:Date.now()},{type:'STREAM_CONFIG'});this.loadStream(type,url);this.setLiveState('LIVE');},
 loadStream(type,url){const video=document.getElementById('live-video'),frame=document.getElementById('live-frame');video.classList.add('hidden');frame.classList.add('hidden');clearTimeout(this.rtcTimer);if(type==='WEBRTC'){video.classList.remove('hidden');if(['ADMIN','UMPIRE'].includes(T.Auth.role()))this.startWebRTCBroadcast();else this.startWebRTCViewer();}else if(type==='CAMERA'){video.classList.remove('hidden');this.startLocalCamera();}else if(type==='HLS'){video.classList.remove('hidden');if(window.Hls&&Hls.isSupported()){this.hls?.destroy?.();this.hls=new Hls({lowLatencyMode:true});this.hls.loadSource(url);this.hls.attachMedia(video);this.hls.on(Hls.Events.MANIFEST_PARSED,()=>video.play().catch(()=>{}));}else{video.src=url;video.play().catch(()=>{});}}else{frame.classList.remove('hidden');frame.src=url;}this.rtcTimer=setTimeout(()=>{if(type==='CAMERA'&&(!video.srcObject||video.readyState<2)){document.getElementById('stream-fallback').classList.remove('hidden')}},5000);},
