 renderFinance(){const rows=Object.values(this.state.finance||{}).sort((a,b)=>a.seq-b.seq),box=document.getElementById('finance-list');box.replaceChildren();const frag=document.createDocumentFragment();let income=0,expense=0;rows.forEach(r=>{if(r.type==='INCOME')income+=r.amount;else expense+=r.amount;const tr=document.createElement('tr');[r.seq,r.date,r.type,r.category,U.money(r.amount),r.invoice,r.receiptState,r.status||'REQUESTED'].forEach(x=>{const td=document.createElement('td');td.textContent=x;tr.appendChild(td)});const td=document.createElement('td');if(r.receiptUrl){const a=document.createElement('a');a.href=r.receiptUrl;a.target='_blank';a.textContent='Tải';td.appendChild(a)}if(T.Auth.role()==='ADMIN'&&r.status!=='PAID'){const b=document.createElement('button');b.className='btn mini ok';b.textContent=r.status==='APPROVED'?'Đã thanh toán':'Duyệt';b.onclick=()=>this.advanceFinance(r.id);td.appendChild(b)}tr.appendChild(td);frag.appendChild(tr)});U.setText('finance-income',U.money(income));U.setText('finance-expense',U.money(expense));U.setText('finance-balance',U.money(income-expense));box.appendChild(frag);},
