 heartbeat(){clearInterval(this.hb);const send=()=>{if(!T.Data.ready||!T.Auth.user)return;const row={uid:T.Auth.user.uid,name:T.Auth.profile?.displayName||T.Auth.user.email,role:T.Auth.role(),online:navigator.onLine,lastSeen:Date.now(),tab:this.currentTab,pending:T.Data.pending};T.Data.db.ref(`${T.ROOT}/health/${T.Auth.user.uid}`).set(row).catch(()=>{})};send();this.hb=setInterval(send,30000);},
