 async deleteCourt(id){const c=this.state.courts?.[id];if(!c)return;if(c.activeMatchId||this.state.activeMatches?.[id])return U.toast('Không thể xóa sân đang có trận LIVE','err');const refs=Object.values(this.state.matches||{}).filter(m=>m.courtId===id),protectedRefs=refs.filter(m=>['LIVE','FINISHED','WALKOVER','RETIRED','DISQUALIFIED'].includes(m.status)||(m.sets||[]).length);if(protectedRefs.length)return U.toast(`Không thể xóa: ${protectedRefs.length} trận đã thi đấu đang lưu lịch sử sân này. Hãy đổi tên sân thay vì xóa.`,'err');const ok=await U.confirmDanger('Xóa '+c.name,refs.length?`${refs.length} trận chưa đấu đang gán sân này sẽ được chuyển về Chưa gán sân.`:'Sân chưa có lịch sử trận.','XÓA SÂN');if(!ok)return;const updates={[T.Data.path('courts/'+id)]:null};refs.forEach(m=>updates[T.Data.path('matches/'+m.id)]={...m,courtId:'',updatedAt:Date.now()});await T.Data.queueMulti(updates,{type:'COURT_DELETE'});await T.Data.audit('DELETE','court',id,c,{unassignedMatches:refs.length});U.toast(`Đã xóa sân${refs.length?` và bỏ gán ${refs.length} trận`:''}`,'ok')},
 schedulerConfig(){const s=this.state.config?.scheduler||{};return{busy:Array.isArray(s.busy)?s.busy:[],priority:Array.isArray(s.priority)?s.priority:[],limits:Array.isArray(s.limits)?s.limits:[],lockedDates:Array.isArray(s.lockedDates)?s.lockedDates:[]}},
 async saveSchedulerConfig(next,type){const before=this.state.config||{},after={...before,scheduler:next,updatedAt:Date.now()};await T.Data.queueSet('config',after,{type});await T.Data.audit('UPDATE','scheduler',T.Data.tid,before.scheduler||{},next)},
 selectedTeamIds(gridId){return[...document.querySelectorAll(`#${gridId} input[type="checkbox"][data-team-id]:checked`)].map(x=>x.dataset.teamId).filter(Boolean)},
 toggleTeamPicker(gridId,checked){document.querySelectorAll(`#${gridId} input[type="checkbox"][data-team-id]`).forEach(x=>{if(!x.disabled)x.checked=checked})},
 renderTeamPicker(id,teams,{disableWithdrawn=false,onlyActive=false}={}){const box=document.getElementById(id);if(!box)return;const selected=new Set(this.selectedTeamIds(id));box.replaceChildren();teams.filter(t=>!onlyActive||!t.withdrawn).forEach(t=>{const label=document.createElement('label');label.className='team-pick'+(t.withdrawn?' withdrawn':'');const cb=document.createElement('input');cb.type='checkbox';cb.dataset.teamId=t.id;cb.checked=selected.has(t.id);cb.disabled=!!(disableWithdrawn&&t.withdrawn);const text=document.createElement('span');text.innerHTML=`<b>${this.escape(t.code||'')}</b> · ${this.escape(t.name)} <small>${this.escape(t.category||'')}</small>${t.withdrawn?' <em>BỎ CUỘC</em>':''}`;label.append(cb,text);box.appendChild(label)});if(!box.children.length){const e=document.createElement('span');e.className='muted';e.textContent='Chưa có đội';box.appendChild(e)}},
 localDateISO(d=new Date()){const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`},
 renderSchedulerControls(){const teams=Object.values(this.state.teams||{}).sort((a,b)=>(a.code||'').localeCompare(b.code||'')||(a.name||'').localeCompare(b.name||''));const today=this.localDateISO(),plus=this.localDateISO(new Date(Date.now()+2*86400000));['auto-date','busy-date','priority-from','limit-from','lock-date'].forEach(id=>{const e=document.getElementById(id);if(e&&!e.value)e.value=today});['auto-end-date','priority-to','limit-to'].forEach(id=>{const e=document.getElementById(id);if(e&&!e.value)e.value=plus});this.renderTeamPicker('busy-team-grid',teams,{disableWithdrawn:true});this.renderTeamPicker('priority-team-grid',teams,{disableWithdrawn:true});this.renderTeamPicker('limit-team-grid',teams,{disableWithdrawn:true});this.renderTeamPicker('withdraw-team-grid',teams,{onlyActive:true});const cfg=this.schedulerConfig(),render=(id,arr,fmt,kind)=>{const box=document.getElementById(id);if(!box)return;box.replaceChildren();arr.forEach((x,i)=>{const d=document.createElement('div');d.className='rule-chip';const span=document.createElement('span');span.textContent=fmt(x);const b=document.createElement('button');b.className='btn mini danger';b.type='button';b.textContent='×';b.onclick=()=>this.removeSchedulerRule(kind,i);d.append(span,b);box.appendChild(d)});if(!arr.length){const e=document.createElement('span');e.className='muted';e.textContent='Chưa có';box.appendChild(e)}};render('lock-date-list',cfg.lockedDates,x=>`🔒 ${x}`,'lockedDates');render('busy-list',cfg.busy,x=>`${this.teamName(x.teamId)} · bận ${x.date}`,'busy');render('priority-list',cfg.priority,x=>`${this.teamName(x.teamId)} · ưu tiên ${x.from} → ${x.to}`,'priority');render('limit-list',cfg.limits,x=>`${this.teamName(x.teamId)} · ${x.from} → ${x.to} · tối đa ${x.max}/ngày`,'limits');const wd=document.getElementById('withdraw-list');if(wd){wd.replaceChildren();teams.filter(t=>t.withdrawn).forEach(t=>{const d=document.createElement('div');d.className='rule-chip withdrawn-chip';const span=document.createElement('span');span.textContent=`🏳️ ${t.code||''} · ${t.name} · đã loại khỏi xếp lịch`;const b=document.createElement('button');b.className='btn mini ok';b.type='button';b.textContent='Khôi phục';b.onclick=()=>this.toggleWithdrawn(t.id);d.append(span,b);wd.appendChild(d)});if(!wd.children.length){const e=document.createElement('span');e.className='muted';e.textContent='Chưa có đội bỏ cuộc';wd.appendChild(e)}}},
 async addLockedDate(){const date=document.getElementById('lock-date').value;if(!date)return U.toast('Chọn ngày cần giữ nguyên','err');const cfg=this.schedulerConfig();if(!cfg.lockedDates.includes(date))cfg.lockedDates.push(date);cfg.lockedDates.sort();await this.saveSchedulerConfig(cfg,'SCHED_LOCK_DATE');U.toast(`Đã khóa ngày ${date}; Smart Scheduler sẽ không xếp/đổi lịch ngày này`,'ok')},
 async addBusyException(){const teamIds=this.selectedTeamIds('busy-team-grid'),date=document.getElementById('busy-date').value;if(!teamIds.length||!date)return U.toast('Tick ít nhất 1 đội và chọn ngày bận','err');const cfg=this.schedulerConfig();let added=0;teamIds.forEach(teamId=>{if(!cfg.busy.some(x=>x.teamId===teamId&&x.date===date)){cfg.busy.push({teamId,date});added++}});await this.saveSchedulerConfig(cfg,'SCHED_BUSY_MULTI');U.toast(`Đã áp dụng ngày bận ${date} cho ${added||teamIds.length} đội`,'ok')},
 async addPriorityWindow(){const teamIds=this.selectedTeamIds('priority-team-grid'),from=document.getElementById('priority-from').value,to=document.getElementById('priority-to').value;if(!teamIds.length||!from||!to||to<from)return U.toast('Tick ít nhất 1 đội và chọn khoảng ưu tiên hợp lệ','err');const cfg=this.schedulerConfig();let added=0;teamIds.forEach(teamId=>{if(!cfg.priority.some(x=>x.teamId===teamId&&x.from===from&&x.to===to)){cfg.priority.push({teamId,from,to});added++}});await this.saveSchedulerConfig(cfg,'SCHED_PRIORITY_MULTI');U.toast(`Đã thêm ${added||teamIds.length} quy tắc ưu tiên`,'ok')},
 async addDailyLimit(){const teamIds=this.selectedTeamIds('limit-team-grid'),from=document.getElementById('limit-from').value,to=document.getElementById('limit-to').value,max=Math.max(1,Math.min(4,Number(document.getElementById('limit-count').value)||1));if(!teamIds.length||!from||!to||to<from)return U.toast('Tick ít nhất 1 đội và chọn khoảng ngày hợp lệ','err');const cfg=this.schedulerConfig();let changed=0;teamIds.forEach(teamId=>{const i=cfg.limits.findIndex(x=>x.teamId===teamId&&x.from===from&&x.to===to);const row={teamId,from,to,max};if(i>=0)cfg.limits[i]=row;else cfg.limits.push(row);changed++});await this.saveSchedulerConfig(cfg,'SCHED_LIMIT_MULTI');U.toast(`Đã áp dụng giới hạn ${max} trận/ngày cho ${changed} đội`,'ok')},
